import{_ as i,a0 as l,w as o,s as d,I as e,x as a,a1 as t,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 Python 讀取電子表格中的數據 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Python 讀取電子表格中的數據 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Python 讀取電子表格中的數據 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Python 讀取電子表格中的數據 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20200330 Using data from spreadsheets in Fedora with Python","title":"使用 Python 讀取電子表格中的數據","tag":"202004","desc":""},"relativePath":"202004/20200330 Using data from spreadsheets in Fedora with Python.md","filePath":"[post].md"}'),h={name:"202004/20200330 Using data from spreadsheets in Fedora with Python.md"};function m(g,s,u,c,f,k){const n=l("Link");return o(),d("div",null,[s[22]||(s[22]=e("h1",{id:"使用-python-讀取電子表格中的數據",tabindex:"-1"},[a("使用 Python 讀取電子表格中的數據 "),e("a",{class:"header-anchor",href:"#使用-python-讀取電子表格中的數據","aria-label":"Permalink to “使用 Python 讀取電子表格中的數據”"},"​")],-1)),s[23]||(s[23]=e("p",null,[e("img",{src:"https://fedoramagazine.org/wp-content/uploads/2020/03/spreadsheets-python-816x345.jpg",alt:""})],-1)),e("p",null,[t(n,{href:"https://python.org"},{default:p(()=>[...s[0]||(s[0]=[a("Python",-1)])]),_:1}),s[1]||(s[1]=a(" 是最流行、功能最強大的編程語言之一。由於它是自由開源的，因此每個人都可以使用。大多數 Fedora 系統都已安裝了該語言。Python 可用於多種任務，其中包括處理逗號分隔值（CSV）數據。CSV文件一開始往往是以表格或電子表格的形式出現。本文介紹瞭如何在 Python 3 中處理 CSV 數據。",-1))]),s[24]||(s[24]=r(`<p>CSV 數據正如其名。CSV 文件按行放置數據，數值之間用逗號分隔。每行由相同的<em>字段</em>定義。簡短的 CSV 文件通常易於閲讀和理解。但是較長的數據文件或具有更多字段的數據文件可能很難用肉眼解析，因此在這種情況下計算機做得更好。</p><p>這是一個簡單的示例，其中的字段是 <code>Name</code>、<code>Email</code> 和 <code>Country</code>。在此例中，CSV 數據將字段定義作為第一行，儘管並非總是如此。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Name,Email,Country</span></span>
<span class="line"><span>John Q. Smith,jqsmith@example.com,USA</span></span>
<span class="line"><span>Petr Novak,pnovak@example.com,CZ</span></span>
<span class="line"><span>Bernard Jones,bjones@example.com,UK</span></span></code></pre></div><h3 id="從電子表格讀取-csv" tabindex="-1">從電子表格讀取 CSV <a class="header-anchor" href="#從電子表格讀取-csv" aria-label="Permalink to “從電子表格讀取 CSV”">​</a></h3><p>Python 包含了一個 <code>csv</code> 模組，它可讀取和寫入 CSV 數據。大多數電子表格應用，無論是原生（例如 Excel 或 Numbers）還是基於 Web 的（例如 Google Sheet），都可以導出 CSV 數據。實際上，許多其他可發佈表格報告的服務也可以導出為 CSV（例如，PayPal）。</p><p>Python <code>csv</code> 模組有一個名為 <code>DictReader</code> 的內置讀取器方法，它可以將每個數據行作為有序字典 （<code>OrderedDict</code>） 處理。它需要一個文件對象訪問 CSV 數據。因此，如果上面的文件在當前目錄中為 <code>example.csv</code>，那麼以下代碼段是獲取此數據的一種方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>f = open(&#39;example.csv&#39;, &#39;r&#39;)</span></span>
<span class="line"><span>from csv import DictReader</span></span>
<span class="line"><span>d = DictReader(f)</span></span>
<span class="line"><span>data = []</span></span>
<span class="line"><span>for row in d:</span></span>
<span class="line"><span>    data.append(row)</span></span></code></pre></div><p>現在，內存中的 <code>data</code> 對象是 <code>OrderedDict</code> 對象的列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[OrderedDict([(&#39;Name&#39;, &#39;John Q. Smith&#39;),</span></span>
<span class="line"><span>               (&#39;Email&#39;, &#39;jqsmith@example.com&#39;),</span></span>
<span class="line"><span>               (&#39;Country&#39;, &#39;USA&#39;)]),</span></span>
<span class="line"><span>  OrderedDict([(&#39;Name&#39;, &#39;Petr Novak&#39;),</span></span>
<span class="line"><span>               (&#39;Email&#39;, &#39;pnovak@example.com&#39;),</span></span>
<span class="line"><span>               (&#39;Country&#39;, &#39;CZ&#39;)]),</span></span>
<span class="line"><span>  OrderedDict([(&#39;Name&#39;, &#39;Bernard Jones&#39;),</span></span>
<span class="line"><span>               (&#39;Email&#39;, &#39;bjones@example.com&#39;),</span></span>
<span class="line"><span>               (&#39;Country&#39;, &#39;UK&#39;)])]</span></span></code></pre></div><p>引用這些對象很容易：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; print(data[0][&#39;Country&#39;])</span></span>
<span class="line"><span>USA</span></span>
<span class="line"><span>&gt;&gt;&gt; print(data[2][&#39;Email&#39;])</span></span>
<span class="line"><span>bjones@example.com</span></span></code></pre></div><p>順便説一句，如果你需要處理沒有字段名標題行的 CSV 文件，那麼 <code>DictReader</code> 類可以讓你定義它們。在上面的示例中，添加 <code>fieldnames</code> 參數並傳遞一系列名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>d = DictReader(f, fieldnames=[&#39;Name&#39;, &#39;Email&#39;, &#39;Country&#39;])</span></span></code></pre></div><h3 id="真實例子" tabindex="-1">真實例子 <a class="header-anchor" href="#真實例子" aria-label="Permalink to “真實例子”">​</a></h3><p>我最近想從一長串人員名單中隨機選擇一箇中獎者。我從電子表格中提取的 CSV 數據是一個簡單的名字和郵件地址列表。</p><p>幸運的是，Python 有一個有用的 <code>random</code> 模組，可以很好地生成隨機值。該模組 <code>Random</code> 類中的 <code>randrange</code> 函數正是我需要的。你可以給它一個常規的數字範圍（例如整數），以及它們之間的步長值。然後，該函數會生成一個隨機結果，這意味着我可以在數據的總行數範圍內獲得一個隨機整數（或者説是行號）。</p><p>這個小程序運行良好：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from csv import DictReader</span></span>
<span class="line"><span>from random import Random</span></span>
<span class="line"><span></span></span>
<span class="line"><span>d = DictReader(open(&#39;mydata.csv&#39;))</span></span>
<span class="line"><span>data = []</span></span>
<span class="line"><span>for row in d:</span></span>
<span class="line"><span>    data.append(row)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>r = Random()</span></span>
<span class="line"><span>winner = data[r.randrange(0, len(data), 1)]</span></span>
<span class="line"><span>print(&#39;The winner is:&#39;, winner[&#39;Name&#39;])</span></span>
<span class="line"><span>print(&#39;Email address:&#39;, winner[&#39;Email&#39;])</span></span></code></pre></div><p>顯然，這個例子非常簡單。電子表格本身包含了複雜的分析數據的方法。但是，如果你想在電子表格應用之外做某事，Python 或許是一種技巧！</p>`,19)),e("p",null,[s[4]||(s[4]=a("題圖由 ",-1)),t(n,{href:"https://unsplash.com/@isaacmsmith?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:p(()=>[...s[2]||(s[2]=[a("Isaac Smith",-1)])]),_:1}),s[5]||(s[5]=a(" 拍攝，發表於 ",-1)),t(n,{href:"https://unsplash.com/s/photos/spreadsheets?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:p(()=>[...s[3]||(s[3]=[a("U​​nsplash",-1)])]),_:1}),s[6]||(s[6]=a("。",-1))]),s[25]||(s[25]=e("hr",null,null,-1)),e("p",null,[s[8]||(s[8]=a("via: ",-1)),t(n,{href:"https://fedoramagazine.org/using-data-from-spreadsheets-in-fedora-with-python/"},{default:p(()=>[...s[7]||(s[7]=[a("https://fedoramagazine.org/using-data-from-spreadsheets-in-fedora-with-python/",-1)])]),_:1})]),e("p",null,[s[13]||(s[13]=a("作者：",-1)),t(n,{href:"https://fedoramagazine.org/author/pfrields/"},{default:p(()=>[...s[9]||(s[9]=[a("Paul W. Frields",-1)])]),_:1}),s[14]||(s[14]=a(" 選題：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 譯者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:p(()=>[...s[11]||(s[11]=[a("geekpi",-1)])]),_:1}),s[16]||(s[16]=a(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[19]||(s[19]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:p(()=>[...s[18]||(s[18]=[a("Linux中國",-1)])]),_:1}),s[21]||(s[21]=a(" 榮譽推出",-1))])])}const x=i(h,[["render",m]]);export{C as __pageData,x as default};
